-- Upload-ready SQL for 50 completed generated posts

-- sql: 10100013001134-tape20
START TRANSACTION;
SET @existing_post=(SELECT ID FROM `ha_posts` WHERE `post_name`='املش-گیلان-navar-tip-20cm' OR (`post_type`='gilan' AND `post_title`='خرید نوار تیپ ۲۰ سانتی در املش') LIMIT 1);
SET @post_id=COALESCE(@existing_post,LAST_INSERT_ID());
COMMIT;


